css:
.print-format { padding: 4mm !important; }
.mdl-sheet { display: flex; flex-wrap: wrap; gap: 3mm; }
.mdl { width: 60mm; height: 38mm; border: 1px solid #000; border-radius: 2mm; padding: 1.5mm 2mm; box-sizing: border-box;
  font-family: Arial, sans-serif; color: #000; page-break-inside: avoid; overflow: hidden; }
.mdl-top { background: #000; color: #fff; text-align: center; font-weight: bold; font-size: 11px; letter-spacing: 2px; margin: -1.5mm -2mm 1mm; padding: 0.5mm 0; }
.mdl-name { font-size: 11px; font-weight: bold; line-height: 1.15; height: 25px; overflow: hidden; }
.mdl-prices { display: flex; justify-content: space-between; align-items: baseline; }
.mdl-was { font-size: 10px; text-decoration: line-through; }
.mdl-now { font-size: 17px; font-weight: bold; }
.mdl-bc { text-align: center; }
.mdl-bc svg { max-width: 100%; }
.mdl-foot { font-size: 8px; text-align: center; }
@page { size: A4; margin: 6mm; }

html:
{%- set cur = frappe.db.get_value("Company", doc.company, "default_currency") -%}
{%- macro m(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{%- endmacro -%}
<div class="mdl-sheet">
{%- for l in doc.labels if not l.used %}
  <div class="mdl">
    <div class="mdl-top">{{ _("REDUCED") }}</div>
    <div class="mdl-name">{{ doc.item_name or doc.item_code }}</div>
    <div class="mdl-prices"><span class="mdl-was">{{ _("Was") }} {{ m(doc.original_price) }}</span>
      <span class="mdl-now">{{ m(doc.markdown_price) }}</span></div>
    <div class="mdl-bc">{{ posa_barcode_svg(l.code, 34, 1.15) }}</div>
    <div class="mdl-foot">{% if doc.valid_upto or doc.expiry_date %}{{ _("Sell by") }} {{ frappe.utils.formatdate(doc.valid_upto or doc.expiry_date) }}{% endif %}
      {% if doc.batch_no %} · {{ doc.batch_no }}{% endif %}</div>
  </div>
{%- endfor %}
</div>
